package com.example.starter.api.dto;

import com.fasterxml.jackson.annotation.JsonFormat;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;

import java.time.Instant;

/**
 * 单个弃用窗口登记请求。
 *
 * <p>effectiveAt 为弃用生效 UTC 时刻，不得早于服务端当前时钟；
 * 替代版本必须与被弃用版本同名且未撤回。
 */
public record DeprecationRequest(
        @NotBlank String name,
        @Positive int version,
        @NotNull
        @JsonFormat(shape = JsonFormat.Shape.STRING)
        Instant effectiveAt,
        @Positive int replacementVersion,
        @Size(max = 512) String note) {
}

package com.example.starter.api.dto;

import com.fasterxml.jackson.annotation.JsonFormat;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 批量设置弃用窗口请求：先对完整替代图统一校验，任一失败整批不写入。
 */
public record BatchDeprecationRequest(
        @Valid @NotEmpty @Size(max = 50) List<@Valid DeprecationRequest> items) {

    public BatchDeprecationRequest {
        if (items != null) {
            items = List.copyOf(items);
        }
    }
}

package com.example.starter.api.dto;

import java.util.List;

/**
 * 批量设置弃用窗口结果。
 *
 * @param requestedCount 要求写入的窗口数量（入参条数，含对同一版本的重复键以 422 拒绝时不产生本响应）
 * @param appliedCount   实际写入的窗口数量（成功时与 requestedCount 相同）
 * @param windows        实际写入后的窗口视图，按制品、版本稳定排序
 */
public record BatchDeprecationResponse(
        int requestedCount,
        int appliedCount,
        List<DeprecationResponse> windows) {
}

package com.example.starter.api.dto;

import java.time.Instant;

/**
 * 锁定解析时闭包内命中的“已生效”弃用项，422 响应中按制品、版本稳定排序返回。
 *
 * @param name               被弃用制品名称
 * @param version            被弃用精确版本号
 * @param replacementName    替代制品名称（与 name 相同）
 * @param replacementVersion 替代版本号
 * @param effectiveAt        弃用生效 UTC 时刻（resolvedAt &gt;= 该值）
 */
public record DeprecatedBlockedItem(
